"""Declarative, accessible simulator shells used by the static Education renderer."""
import html
E=lambda x:html.escape(str(x),quote=True)
def slider(name,label,lo,hi,step,value):
 return {'name':name,'label':label,'min':lo,'max':hi,'step':step,'value':value,'kind':'range'}
def select(name,label,options,value):return {'name':name,'label':label,'options':options,'value':value,'kind':'select'}
WIDGETS=[
 {'id':'light-photon','module':'light','title':'Tune a photon','caption':'Drag the spectrum or move the wavelength slider. Shorter wavelength means higher frequency and photon energy.','kind':'Exact vacuum unit conversions · approximate screen colors','controls':[slider('wavelength','Vacuum wavelength (nm)',380,780,1,550)],'sources':['constants'],'notes':'E = hc/λ; ν = c/λ. The color strip is original illustrative RGB interpolation, not calibrated human color perception; visible limits vary. J is energy, Hz is frequency.','teacher':'Predict the change in E when wavelength doubles. Compare 400 nm with 780 nm and explain the inverse relationship.'},
 {'id':'dispersion','module':'light','title':'Prism or diffraction grating?','caption':'Compare two different ways to spread wavelengths. Each ray is colored by the same approximate color scale.','kind':'Analytic optics · schematic ray layout','controls':[slider('wavelength','Selected wavelength (nm)',400,700,1,550),slider('apex','Prism apex angle (degrees)',30,60,1,60),slider('grooves','Grating groove density (lines/mm)',200,1200,50,600),select('order','Diffraction order',[(str(n),str(n)) for n in [-2,-1,0,1,2]],'1')],'sources':['glass','grating'],'notes':'Prism: SCHOTT N-BK7 Sellmeier n(λ), minimum deviation δ = 2 asin(n sin(A/2)) − A. Each wavelength is evaluated at its own minimum-deviation incidence; the illustration is not a common-incidence ray trace. Grating: normal incidence in vacuum, d sin θ = mλ. An order with |mλ/d| > 1 does not propagate. Prism refraction is not diffraction. Angles and angular dispersion are numeric; ray positions are schematic.','teacher':'Compare red and blue: which has the larger prism deviation? Which has the larger grating angle in order +1? What happens in order zero or when an order is forbidden?'},
 {'id':'resolution','module':'light','title':'Separate two nearby lines','caption':'The cyan curve is a noise-free teaching profile; orange points illustrate detector sampling and seeded Gaussian noise.','kind':'Gaussian line-spread approximation · not a measured HARPS profile','controls':[slider('R','Resolving power R (dimensionless)',20000,150000,1000,115000),slider('separation','Line separation (nm)',.002,.04,.001,.006),slider('sampling','Samples per instrumental FWHM',1,8,.1,4.1),slider('snr','Continuum signal-to-noise per sample',20,300,10,100)],'sources':['harps','harps-manual','harps-profile'],'notes':'At 550 nm, instrumental FWHM = λ/R. Intrinsic Gaussian sigma is 0.0005 nm, convolved analytically with the Gaussian instrument profile. R, sampling and noise are separate. ESO overview gives nominal HARPS R=115,000; manual 3.3.12 lists measured R=120,000 and 4.1 pixels/FWHM. The two presets retain this distinction. Real HARPS line-spread functions are not universally Gaussian. Distinguishability depends on line shape, contrast, sampling, SNR and inference method; there is no universal hard threshold.','teacher':'Hold R fixed and reduce SNR, then change sampling alone. Which properties of the noise-free line stay unchanged?','presets':[('HARPS nominal',{'R':115000,'sampling':4.1}),('HARPS manual measured R',{'R':120000,'sampling':4.1})]},
 {'id':'doppler','module':'light','title':'Move a spectrum toward or away','caption':'Cyan: stationary reference. Orange: shifted copies of the same three hypothetical absorption lines.','kind':'Longitudinal special-relativistic Doppler shift','controls':[slider('velocity','Radial velocity (km/s; positive receding)',-300,300,.000001,30)],'sources':['constants','planet'],'notes':'λobs/λrest = sqrt((1+β)/(1−β)), β=v/c. The approximation Δλ/λ ≈ v/c applies for |v| ≪ c; compare its error in the readout. Hypothetical reference lines at 499.7, 500.0 and 500.3 nm are not element identifications. Only longitudinal motion is modeled.','teacher':'Set v to equal positive and negative values. Explain the sign, then follow the link to stellar reflex motion in the RV simulator.'},
 {'id':'stellar-simulator','module':'stellar-spectroscopy','title':'Stellar Spectroscopy Simulator','caption':'Compare a weak and a saturated synthetic teaching line under the same parameters. Dashed lines retain the reference atmosphere for comparison.','kind':'Schematic LTE absorbing slab · not a validated stellar atmosphere grid','controls':[slider('teff','Effective temperature proxy Teff (K)',4500,7000,1,5772),slider('logg','Surface gravity log g (cgs)',3,5,.01,4.44),slider('metallicity','Metallicity [M/H] (dex)',-1.5,1,.05,0),slider('xi','Microturbulence ξ (km/s)',0,5,.1,1),slider('R','Instrument resolving power R',20000,150000,1000,115000)],'sources':['saha','cog','constants'],'notes':'This is a generic Fe-like atom (56 u, ionization 7.9 eV, excitation 2.5 eV), not an identified observed transition. A single LTE absorbing screen uses F=exp(−τ); opacity scales with 10^[M/H] and Saha–Boltzmann populations. T is set equal to Teff. Electron density ne=10¹⁹ × 10^(log g−4.44) × 5772/T m⁻³ is an explicit schematic pressure proxy, not a calibrated atmosphere. Doppler b²=2kT/m+ξ²; the area-normalized opacity is broadened before transfer. Only instrumental broadening is a subsequent convolution. No line emission, damping, real atmosphere, NLTE or 3D prediction. Slider bounds define the teaching domain, not an interpolation grid.','teacher':'Hold abundance fixed, increase ξ and compare weak/saturated EW. Change R alone: profiles change while integrated EW is conserved if the window contains the full line. Explore gravity–metallicity and temperature degeneracies; different parameters can give similar line strengths.','presets':[('Reference',{'teff':5772,'logg':4.44,'metallicity':0,'xi':1,'R':115000}),('Lower resolution only',{'R':25000}),('More microturbulence only',{'xi':4})]},
 {'id':'equivalent-width','module':'elemental-abundances','title':'Measure the missing light','caption':'The shaded area is the signed integrated difference between the adopted continuum and normalized flux within the selected window.','kind':'Analytic line profile · numerical area integral','controls':[slider('depth','Line depth below true continuum',.05,.9,.01,.5),slider('sigma','Gaussian sigma / Lorentz HWHM (Å)',.02,.3,.01,.1),select('shape','Line shape',[('gaussian','Gaussian'),('lorentzian','Lorentzian')],'gaussian'),slider('window','Integration half-window (Å)',.03,1.5,.01,.5),slider('continuum','Adopted continuum / true continuum',.95,1.05,.005,1)],'sources':['cog'],'notes':'Wλ = ∫[1−Fλ/Fc]dλ; 1 Å = 1000 mÅ. The center is a hypothetical 5000 Å (500 nm) line. Depth and width are independent synthetic teaching inputs. Gaussian full EW = depth × sigma × sqrt(2π); FWHM = 2 sqrt(2 ln 2) sigma and is not EW. A finite window can lose area. Continuum errors can add or subtract area, including a signed negative result. The Lorentzian width control is HWHM, not sigma.','teacher':'Change depth and width separately. Then keep the physical line fixed and offset the continuum: is the inferred EW unbiased? Compare the area result with FWHM.'},
 {'id':'curve-growth','module':'elemental-abundances','title':'From equivalent width to abundance — conditionally','caption':'Move along a synthetic curve of growth. Compare two Doppler widths at the same abundance and inspect a line profile.','kind':'Fixed absorbing-screen curve of growth · synthetic differential abundance','controls':[slider('abundance','Log abundance ratio to synthetic reference (dex)',-2,2,.05,0),slider('b','Doppler b parameter (km/s)',1,8,.1,2)],'sources':['cog'],'notes':'F(v)=exp[−A φ(v)] with unit-area Gaussian φ, A=5×10^ΔA km/s and sigma=b/√2. W is integrated and converted at a hypothetical 500 nm line. Inversion uses the same fixed transition strength and atmosphere proxy; it returns only a synthetic differential abundance, not a calibrated A(X) or Codex result. This Gaussian-opacity model shows linear and saturation regimes, not the damping-wing branch. Increasing b can increase saturated EW at unchanged abundance. Instrument convolution conserves full EW and is distinct from opacity broadening.','teacher':'Compare b=2 and b=6 at ΔA=−2 and +1. An EW-to-abundance conversion requires the transition, populations, broadening and transfer assumptions to be held fixed.','extra':'EW/curve-of-growth uses integrated area; profile fitting and spectral synthesis compare wavelength-dependent flux and blends. These are methods, not engines. LTE/NLTE concerns populations and radiation; 1D/mean-3D/full-3D concerns structure/transfer. Codex registry distinguishes these axes; named engines have line- and model-dependent applicability, not blanket certification.','extra_link':'/method/#measuring'},
 {'id':'transit-simulator','module':'exoplanets','title':'Build a transit light curve','caption':'Change planet size, impact parameter and limb darkening; scrub the planet across the projected stellar disk.','kind':'Circular orbit geometry · linear limb-darkening quadrature','controls':[slider('radius','Planet/star radius ratio Rp/R★',.02,.3,.01,.1),slider('impact','Impact parameter b (stellar radii)',0,1.4,.02,.2),slider('limb','Linear limb-darkening coefficient u',0,.9,.05,.6),slider('phase','Time from mid-transit (hours)',-4,4,.05,0)],'sources':['transit'],'notes':'Opaque spherical planet and spherical star, circular orbit, a/R★=10 and P=3 days fixed. Impact parameter b=(a/R★) cos i determines geometry. Linear intensity I(μ)=1−u(1−μ), with disk normalization π(1−u/3). Uniform disks use exact circle overlap; limb darkening uses 900 radial annuli. No spots, dilution, exposure averaging or transit timing variations. a/R★ and P imply a fixed stellar-density scale; no stellar mass/radius is inferred here. This is a teaching implementation, not batman or a fitted planet.','teacher':'Try b>1+Rp/R★: no transit. At b=0,u=0 verify depth=(Rp/R★)². Increase u and inspect how the curve changes; radius and limb darkening can trade off.'},
 {'id':'rv-simulator','module':'exoplanets','title':'Watch a star’s reflex motion','caption':'The star, not the planet, supplies these shifted stellar lines. Phase is interactive; the orbit sketch is deliberately not to scale.','kind':'Circular two-body orbit · no eccentricity or stellar activity','controls':[slider('mass','Planet mass (Jupiter masses)',.01,5,.01,1),slider('inclination','Orbital inclination (degrees)',0,90,1,90),slider('period','Orbital period (days)',1,365,1,30),slider('starMass','Stellar mass (solar masses)',.5,2,.05,1),slider('phase','Orbital phase (cycles)',0,1,.01,.25)],'sources':['planet','iau','constants'],'notes':'For e=0, K=(2πG/P)^(1/3) Mp sin i/(M★+Mp)^(2/3), v★=K sin(2π phase). Positive v is receding. Masses use the documented IAU nominal-GM/G conversion. Without inclination, RV constrains a mass function; Mp sin i is the usual small-Mp/M★ minimum-mass approximation. We retain Mp in the denominator. Doppler-shift readout is relativistic; the curve is nonrelativistic two-body motion. The linked spectral line width is illustrative and magnified for teaching, not an instrument line-spread function. No eccentricity, activity, blends or additional planets.','teacher':'Set i=0: why is RV zero even for a massive planet? Double mass or change period, then compare the Doppler shift with the Light lesson.','presets':[('Jupiter-like circular',{'mass':1,'inclination':90,'period':365,'starMass':1}),('Face-on',{'inclination':0})]},
 {'id':'atomic-metadata','module':'atomic-laboratory','title':'Inspect the source behind a line','caption':'Choose an element and line, then compare the adopted record with retained source candidates. Unknown fields remain unknown.','kind':'Pinned canonical metadata · no prediction or grade promotion','controls':[select('element','Element',[('Na','Neutral sodium · Na I'),('H','Neutral hydrogen · H I')],'Na'),select('line','Transition / line record',[('sodium-d2','Na D₂'),('sodium-d1','Na D₁'),('ungraded','Additional ungraded canonical Na line'),('balmer-alpha','H Balmer α'),('balmer-beta','H Balmer β'),('lyman-alpha','H Lyman α')],'sodium-d2')],'sources':['lines'],'notes':'NIST level and line tables provide identities. The pinned Codex canonical_gf rows provide adopted log(gf), NIST accuracy grade and retained GES/VALD candidate columns. These historical candidates are not independent new external queries. An accuracy grade describes atomic-data uncertainty, not approval for a stellar analysis. NIST is an evaluated compilation; experimental/theoretical origins are not classified where the snapshot does not establish them. Missing H log(gf) and missing grades stay unknown, not zero. This explorer does not promote Theoretical Atomic Lab candidates.','teacher':'Find a source difference for Na D₁, then select the ungraded line. Which claims can you make from a source value, an accuracy grade or missing provenance? Follow the actual pinned canonical reference.'},
 {'id':'photon-exercise','module':'learning-resources','title':'Try it: predict a photon’s energy','caption':'Tune the light, calculate E=hc/λ, enter your prediction in eV and check it. The result explains units and the calculation.','kind':'Worked interactive assessment · 1% answer tolerance','controls':[slider('wavelength','Vacuum wavelength (nm)',400,750,1,500),{'name':'answer','label':'Your predicted photon energy (eV)','min':.1,'max':20,'step':.001,'value':2,'kind':'number'}],'sources':['constants'],'notes':'Use λ in meters, h=6.62607015×10⁻³⁴ J s and c=299792458 m/s, then divide joules by 1.602176634×10⁻¹⁹ J/eV. Approximate color is an aid, not calibrated colorimetry. The check accepts relative error ≤1%; this is a classroom scoring tolerance, not a physical uncertainty.','teacher':'Ask for a prediction before calculating. At 500 nm expect approximately 2.480 eV. Correct arithmetic with wrong units does not earn full credit. Change to 650 nm and explain the direction before trying again. Link back to the atomic and Light experiments for transfer practice.'}
]
def control(c,wid):
 id=wid+'-'+c['name'];common=f'id="{id}" name="{c["name"]}"'
 if c['kind']=='select':
  field='<select '+common+'>'+''.join(f'<option value="{E(v)}"'+(' selected' if str(v)==str(c['value']) else '')+'>'+E(label)+'</option>' for v,label in c['options'])+'</select>'
 else:field=f'<input {common} type="{c["kind"]}" min="{c["min"]}" max="{c["max"]}" step="{c["step"]}" value="{c["value"]}">'
 return f'<div class="sim-control"><label for="{id}">{E(c["label"])}</label>{field}<output for="{id}" data-value="{c["name"]}">{E(c["value"])}</output></div>'
def widget(w,config):
 id=w['id'];presets=''.join(f'<button type="button" data-preset="{i}">{E(label)}</button>' for i,(label,values) in enumerate(w.get('presets',[])))
 extras=''
 if id=='photon-exercise':extras='<button type="button" data-check>Check my answer</button><p class="exercise-feedback" data-feedback role="status">Make a prediction, then check it.</p>'
 if id=='doppler':extras='<a href="#rv-simulator">Explore stellar reflex motion →</a>'
 if id=='rv-simulator':extras='<button type="button" data-to-doppler>Send this velocity to the Light experiment</button>'
 if 'extra' in w:extras+=f'<p>{E(w["extra"])}</p><p><a href="{w["extra_link"]}">Compare documented Codex measurement methods</a></p>'
 sources=' · '.join(f'<a href="{E(config["sources"][k]["url"])}">{E(config["sources"][k]["title"])}</a>' for k in w['sources'])
 return f'''<section class="science-widget" id="{id}" data-widget="{id}" aria-labelledby="{id}-title">
 <header><span class="experiment-tag">Working experiment</span><h3 id="{id}-title">{E(w['title'])}</h3><p>{E(w['caption'])}</p><p class="model-kind">{E(w['kind'])}</p></header>
 <p data-load role="status">This experiment needs JavaScript. Read the assumptions and worked lesson below when interactive controls are unavailable.</p>
 <form hidden><fieldset class="sim-controls"><legend>Change a parameter</legend>{''.join(control(c,id) for c in w['controls'])}</fieldset><div class="sim-presets">{presets}</div><div class="sim-actions"><button type="reset">Reset experiment</button><button type="button" data-csv>Download data CSV</button><button type="button" data-svg>Download plot SVG</button></div></form>
 <div class="sim-visual" data-visual tabindex="0" role="region" aria-label="{E(w['title'])} plots; scroll horizontally on small screens"><p>Model not loaded; no simulated result is being asserted.</p></div>
 <p data-result class="sim-result" role="status" aria-live="polite"></p><div class="sim-extras">{extras}</div>
 <details><summary>Model, sources &amp; teacher notes</summary><p>{E(w['notes'])}</p><p><strong>Teacher prompt:</strong> {E(w['teacher'])}</p><p>{sources}</p><p>Source checked 2026-11-14. Independent scientific and accessibility review pending.</p><label>Share this experiment configuration<input data-share type="url" readonly aria-label="Share {E(w['title'])}"></label></details></section>'''
def widgets_for(module,config):return ''.join(widget(w,config) for w in WIDGETS if w['module']==module)
def client_definitions():return [{'id':w['id'],'module':w['module'],'controls':w['controls'],'presets':[v for label,v in w.get('presets',[])],'sources':w['sources'],'model':w['notes']} for w in WIDGETS]
